update public.questions as question
set explanation = revised.explanation
from (values
  ('c11-grammar', 0, 'Регистр — это разновидность речи, которую выбирают с учётом ситуации, цели и отношений между собеседниками.'),
  ('c11-grammar', 1, 'Dobór słów означает осознанный выбор лексики: одна и та же мысль может звучать нейтрально, официально или разговорно.'),
  ('c11-grammar', 2, 'Zwrot grzecznościowy — устойчивая формула вежливости, например Szanowna Pani или Z poważaniem, а не просто нейтральное слово.'),
  ('c11-grammar', 3, 'Potoczny описывает непринуждённую разговорную речь; такие формы уместны среди знакомых, но не всегда подходят официальному письму.'),
  ('c11-grammar', 4, 'Neutralny — лишённый подчёркнутой фамильярности и официальности; такой тон подходит широкой аудитории и передаёт смысл без лишней оценки.'),
  ('c11-grammar', 5, 'Oficjalny называют регистр с установленными формулами, точными формулировками и большей дистанцией между автором и адресатом.'),
  ('c11-quiz', 0, 'Rejestr — это регистр речи: набор языковых средств, соответствующий конкретной ситуации общения.'),
  ('c11-quiz', 1, 'Dobór słów — выбор слов; выражение подчёркивает, что автор сознательно подбирает лексику под цель и адресата.'),
  ('c11-quiz', 2, 'Zwrot grzecznościowy — формула вежливости, которая обозначает уважение и регулирует дистанцию между собеседниками.'),
  ('c11-quiz', 3, 'Potoczny значит разговорный: естественный для неофициальной устной речи и близких отношений.'),
  ('c11-quiz', 4, 'Neutralny значит нейтральный: без заметной разговорной окраски и без подчёркнутой официальности.'),
  ('c11-quiz', 5, 'Oficjalny значит официальный; такой стиль соблюдает институциональные нормы и обычно сохраняет дистанцию.'),
  ('c11-quiz', 6, 'Dostosować wypowiedź — адаптировать высказывание, то есть изменить лексику, тон или структуру под конкретного адресата.'),
  ('c11-quiz', 7, 'Zachować dystans — сохранять дистанцию: поддерживать уважительный, не слишком личный характер общения.'),
  ('c11-quiz', 8, 'Skrócić dystans — сократить дистанцию, сделав общение менее формальным и более непосредственным.'),
  ('c11-quiz', 9, 'Brzmieć protekcjonalnie — звучать покровительственно, словно говорящий считает себя компетентнее или выше адресата.'),
  ('c11-reading-check', 0, 'В первом абзаце названы три разных адресата — друг, команда и учреждение, поэтому для каждого понадобился свой тон.'),
  ('c11-reading-check', 1, 'Первый абзац вводит исходную ситуацию целиком: редактор готовит три версии одного сообщения для трёх адресатов.'),
  ('c11-reading-check', 2, 'Второй абзац описывает разговорную версию: она короткая и прямая, но в обращении к учреждению была бы неуместна.'),
  ('c11-reading-check', 3, 'Третий абзац посвящён официальной версии: в ней есть формула вежливости и точная цель, однако тон не становится холодным.'),
  ('c11-reading-check', 4, 'В четвёртом абзаце редактор замечает риск чрезмерной вежливости: она способна прозвучать покровительственно.'),
  ('c11-reading-check', 5, 'Последний абзац формулирует общий вывод: хороший регистр определяется точным соответствием адресату, а не сложностью слов.')
) as revised(lesson_id, position, explanation)
where question.lesson_id = revised.lesson_id
  and question.position = revised.position;
